    }

    const rubbleMat = new THREE.MeshStandardMaterial({ color: 0x5f5e55, roughness: .92, metalness: .03 });
    const rubble = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), rubbleMat, 130);
    const dummy = new THREE.Object3D();
