        }
        if (this.detailWeapon?.id === weaponId) {
          this.dom.detailImage.src = src;
          this.dom.detailImage.style.opacity = '1';
        }
      };
      if (id) apply(id);
      else Object.keys(images).forEach(apply);
    });
  }

