    const g = window.__ZONA_MORTA__;
    const list = g.zombies.zombies.filter(z => !z.dead);
    if (!list.length) return { count: 0 };
    list.sort((a,b) => a.group.position.distanceToSquared(g.player.pos) - b.group.position.distanceToSquared(g.player.pos));
    const z = list[0];
    const eye = g.player.pos.clone(); eye.y += g.player.height;
    const t = z.group.position.clone(); t.y += 1.1;
    const d = t.sub(eye).normalize();
    g.player.yaw = Math.atan2(-d.x, -d.z);
    g.player.pitch = Math.asin(d.y);
    return { count: list.length, dist: +z.group.position.distanceTo(g.player.pos).toFixed(1), zid: z.id };
  });
  for (let i = 0; i < 4; i++) {
    await page.evaluate(() => { const g = window.__ZONA_MORTA__; g.nextFire = 0; g.tryFire(); });
